<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class MessageRetriesVO
{
    public static function from(MessageRetriesVO|int $value): MessageRetriesVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?MessageRetriesVO
    {
        if ($value instanceof MessageRetriesVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_integer($value)) {
            return new MessageRetriesVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['retries'], [$value], ['int']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): MessageRetriesVO
    {
        if ($value instanceof MessageRetriesVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof MessageRetriesVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly int $retries
    ) {
    }
    public function value(): int
    {
        return $this->retries;
    }
    public function equals(?MessageRetriesVO $other): bool
    {
        return $this->value() == $other?->value();
    }
}
